    @Test public void streamParentChildStar() {
        String h = "<div id=1><p>Hello<p><b>there</b></p></div><div id=2><span>Hi</span></div>";
        Document doc = Jsoup.parse(h);

        List<Element> divChilds = doc.selectStream("div > *")
